#!/usr/bin/env python3
"""Generate a self-contained browser explorer and optional Graphviz source.
No graph package is required. HTML renders SVG locally and exports that SVG.
"""
import argparse,json,hashlib,html
from pathlib import Path

def main():
 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--packet-root',type=Path,default=Path(__file__).resolve().parent);ap.add_argument('--result',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();a.out.mkdir(parents=True,exist_ok=False)
 dag=json.loads((a.packet_root/'dag.json').read_text());r=json.loads(a.result.read_text());costs={n['id']:n['costs'] for n in r['additive_leaf_nodes']+r['named_rollups_not_additional_charges']};data=dict(dag=dag,costs=costs,totals=r['costs'],counts=r['node_counts_at_declared_granularity'],headline=r['headline_from_accepted_measurement'],result_sha256=hashlib.sha256(a.result.read_bytes()).hexdigest())
 payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
 template=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projective groups: paired proof dependencies</title>
<style>body{font:16px system-ui,sans-serif;margin:0;color:#192431;background:#fafbfc}header,main{padding:20px 28px}header{background:#102e44;color:white}h1{font-size:26px;margin:0 0 10px}h2{font-size:20px}p{max-width:1050px;line-height:1.5}.headline{display:flex;gap:24px;flex-wrap:wrap}.headline b{font-size:27px;display:block}.small{font-size:13px;line-height:1.5;color:#566778}header .small{color:#d5e3ed}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:15px 0}select,button,input{font:inherit;padding:5px}button{cursor:pointer;border:1px solid #9cabb6;border-radius:4px;background:#fff}.warning{background:#fff3d7;border-left:4px solid #bc831d;padding:9px 14px}.panes{display:grid;grid-template-columns:minmax(300px,1fr) 350px;gap:16px}#canvas{overflow:auto;border:1px solid #bdcbd6;background:white;max-height:72vh;min-height:340px}#detail{font-size:14px;line-height:1.5;border:1px solid #bdcbd6;background:white;padding:14px;overflow:auto;max-height:68vh;overflow-wrap:anywhere}#detail h3{margin:0 0 9px}#detail ul{padding-left:18px}.n{cursor:pointer}.n:hover rect{stroke:#0065b3;stroke-width:3px}.selected rect{stroke:#0065b3;stroke-width:3px}.edge{fill:none;stroke:#93a2ad;stroke-width:1.2}.edge.nonlogical{stroke-dasharray:5 4}.nodeText{font:12px system-ui,sans-serif;fill:#152c3c}.nodeId{font:11px system-ui,sans-serif;fill:#4b5965}.tableWrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{border-bottom:1px solid #cbd5dc;text-align:left;padding:8px;vertical-align:top}th{background:#eaf0f4}code{font-size:12px}details{margin:18px 0}a{color:#075b93}.legend{display:flex;gap:17px;font-size:13px}.legend span:before{content:'■ ';color:var(--color)}@media(max-width:850px){.panes{grid-template-columns:1fr}header,main{padding:16px}#detail{max-height:40vh}}
</style>
<header><h1>Projective groups: where the proofs share work</h1><div id="headline" class="headline"></div><p class="small">Complete historical manuscripts compared with the common theory and three complete applications, under the declared corrected main-result contracts. Conditional application factors assume the common theory has been acquired. This dependency view explains those figures; it does not replace them with a node-count ratio.</p></header>
<main><div class="warning">Historical arrows record arguments used or asserted in the source. Red-bordered nodes retain false-clause or missing-argument qualifications. A dependency closure is the union of the recorded arguments, including both alternatives where a source prints two proofs; it is not a minimum proof or an endorsement of a defective inference.</div>
<div class="controls"><label>Graph <select id="side"><option value="replacement">New common proofs</option><option value="historical">Historical sources</option><option value="all">Both</option></select></label><label>Paper <select id="doc"><option value="all">All papers on this side</option></select></label><label>Detail <select id="gran"><option value="named">Whole results (branches collapsed)</option><option value="expanded">Expanded branches and result interfaces</option></select></label><label><input id="context" type="checkbox">Context</label><label><input id="external" type="checkbox">Retained inputs</label><label><input id="nonlogical" type="checkbox">Diagnostic/adaptation arrows</label><button id="save">Save current SVG</button></div>
<div class="controls"><label>Weight <select id="metric"><option value="characters_without_whitespace">Characters excluding whitespace</option><option value="whitespace_tokens">Whitespace tokens</option><option value="alphanumeric_units">Alphanumeric units</option><option value="characters_with_collapsed_whitespace">Characters, whitespace collapsed</option><option value="utf8_bytes_with_collapsed_whitespace">UTF-8 bytes, whitespace collapsed</option></select></label><label>Normalization <select id="form"><option>NFC</option><option>NFKC</option></select></label><input id="search" placeholder="Find a label or node ID" aria-label="Search nodes"></div>
<div class="legend"><span style="--color:#d9a541">Historical argument</span><span style="--color:#78acd1">New proof</span><span style="--color:#b8bdc3">Retained input, cost unknown</span><span style="--color:#bd574b">Source qualification</span></div><p id="graphSummary" class="small"></p><div class="panes"><div id="canvas"></div><aside id="detail">Select a node to see its full label, exact locators, weights, prerequisites and source qualifications.</aside></div>
<h2>Complete-document costs</h2><p class="small">Every selected character belongs to one leaf. A whole-result box sums its statement and proof children; it is not charged again. The required program and optional validation program have separate complete costs. Full manuscripts remain charged even outside a chosen output's dependency closure.</p><div class="tableWrap"><table id="totals"></table></div>
<details><summary>Declared node conventions and raw counts</summary><p id="granularity"></p><div class="tableWrap"><table id="counts"></table></div><p class="small">Historical numbered items include definitions, retained statements and remarks. New bundled theorems expose substantive branches. These raw counts have different granularity; no count ratio is calculated. Graph topology alone is not a quality measure.</p></details>
<details><summary>Replay and trust boundary</summary><p>Run <code>python check.py --sources-root /path/to/primary-pdfs --artifacts-root /path/to/repository --layout public --out /fresh/report.json</code>. The source directory must contain the three exact bound PDFs. No primary text is distributed in this packet. <code>dag.json</code> preserves every fine dependency edge, <code>partition.json</code> owns every text span, and <code>result.json</code> contains all ten weights and per-output closures.</p><p>Classical proof costs and historical computation costs remain unknown. Required GAP computations have the declared trust boundary; supporting Lean results do not formalize the complete papers. Automatic replay checks accounting and exact bindings, not the truth of a mathematical dependency.</p><p id="hash" class="small"></p></details></main>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent), G=D.dag, by=Object.fromEntries(G.nodes.map(n=>[n.id,n])), parent={};G.nodes.forEach(n=>(n.children||[]).forEach(c=>parent[c]=n.id));const logical=new Set(G.logical_edge_kinds), $=id=>document.getElementById(id), fmt=x=>x===null?'unknown':Number(x).toLocaleString('en-US'), esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let selected=null;
function val(n){return D.costs[n]?.[$('form').value]?.[$('metric').value]??null}function flagged(n){let s=n.documentary_status||'';return /false|overbroad|unprinted|omitted_adapter|qualification_required|not_endorsed|qualified_literal|literal_naming|asserted_without/.test(s)}function ext(n){return n.cost_status==='conditioned_unknown'}function shownProof(n){return /theorem|proof|named_result|computation|validation|retained_statement/.test(n.category)}
function initDocs(){let side=$('side').value,old=$('doc').value;$('doc').innerHTML='<option value="all">All papers on this side</option>'+Object.entries(G.document_metadata).filter(([k,d])=>side==='all'||d.side===side).map(([k,d])=>`<option value="${k}">${esc(d.title)}</option>`).join('');if([...$('doc').options].some(o=>o.value===old))$('doc').value=old}
function tables(){let f=$('form').value,m=$('metric').value;$('totals').innerHTML='<tr><th>Paper / artifact</th><th>Weight</th><th>Physical pages</th></tr>'+Object.entries(G.document_metadata).map(([k,d])=>`<tr><td>${esc(d.title)}<br><code>${k}</code></td><td>${fmt(D.totals[k][f][m])}</td><td>${d.binding.pages}</td></tr>`).join('');$('counts').innerHTML='<tr><th>Document</th><th>Charged owners</th><th>Uncharged rollups</th><th>Exact categories</th></tr>'+Object.entries(D.counts).map(([k,c])=>`<tr><td>${esc(G.document_metadata[k]?.title||k)}</td><td>${c.charged_cost_owners}</td><td>${c.rollup_only}</td><td>${Object.entries(c.categories).map(([a,b])=>esc(a)+': '+b).join('<br>')}</td></tr>`).join('')}
function closure(id){let out=new Set(),todo=[id];while(todo.length){let n=todo.pop();if(out.has(n))continue;out.add(n);G.edges.filter(e=>e.consumer===n&&logical.has(e.kind)).forEach(e=>todo.push(e.prerequisite))}return [...out]}
function detail(id){selected=id;let n=by[id],incoming=G.edges.filter(e=>e.consumer===id&&e.kind!=='result_assembly'),outgoing=G.edges.filter(e=>e.prerequisite===id&&e.kind!=='result_assembly'),cl=closure(id),paid=cl.filter(x=>by[x].cost_status==='measured'),unknown=cl.filter(x=>ext(by[x])),cost=paid.reduce((s,x)=>s+val(x),0);let links=es=>es.map(e=>`<li><a href="#" data-node="${esc(e.prerequisite===id?e.consumer:e.prerequisite)}">${esc(e.prerequisite===id?e.consumer:e.prerequisite)}</a> — ${esc(e.reason||e.kind)} <small>(${esc(e.kind)})</small></li>`).join('');$('detail').innerHTML=`<h3>${esc(n.label)}</h3><code>${esc(id)}</code><p>${esc(G.document_metadata[n.document]?.title||'Retained library')}</p><p><b>Weight: ${fmt(val(id))}</b>${n.cost_status==='rollup_only'?'<br>Full result rollup; not an additional charge.':ext(n)?'<br>Unknown proof cost, never zero.':'<br>Owned text charged once.'}</p>${n.documentary_status?`<p><b>Status:</b> ${esc(n.documentary_status)}</p>`:''}${n.qualification?`<p class="warning">${esc(n.qualification)}</p>`:''}${n.closure_caveat?`<p class="warning">${esc(n.closure_caveat)}</p>`:''}<p>${(n.locators||[]).map(esc).join('<br>')}</p>${n.children?`<p>Parts: ${n.children.map(c=>`<a href="#" data-node="${esc(c)}">${esc(c)}</a>`).join(', ')}</p>`:''}<h4>Recorded prerequisite union</h4><p>${fmt(cost)} known text units across ${paid.length} owned leaves; ${unknown.length} unknown-cost inputs. This is not a minimum proof. Whole-document charges are unchanged.</p><h4>Direct prerequisites</h4><ul>${links(incoming)||'<li>No direct recorded prerequisite.</li>'}</ul><h4>Used by</h4><ul>${links(outgoing)||'<li>No direct recorded consumer.</li>'}</ul>`;$('detail').querySelectorAll('[data-node]').forEach(a=>a.onclick=e=>{e.preventDefault();detail(a.dataset.node)});document.querySelectorAll('.n').forEach(x=>x.classList.toggle('selected',x.dataset.id===id))}
function wrap(s,n=30){let out=[],line='';s.split(/\s+/).forEach(w=>{if((line+' '+w).trim().length>n&&line){out.push(line);line=w}else line+=(line?' ':'')+w});if(line)out.push(line);return out.slice(0,3)}
function render(){let side=$('side').value,doc=$('doc').value,compact=$('gran').value==='named',search=$('search').value.toLowerCase();let ids=G.nodes.filter(n=>{if(ext(n))return $('external').checked;if(side!=='all'&&n.side!==side)return false;if(doc!=='all'&&n.document!==doc)return false;if(compact&&parent[n.id])return false;if(!$('context').checked&&!shownProof(n)&&n.category!=='substantive_unnumbered_proof')return false;return true}).map(n=>n.id);let set=new Set(ids);function map(id){return compact?(parent[id]||id):id}let edges=[],seen=new Set();G.edges.forEach(e=>{if((compact&&e.kind==='result_assembly')||(!$('nonlogical').checked&&!logical.has(e.kind)))return;let a=map(e.prerequisite),b=map(e.consumer);add(a,b,e)});function add(a,b,e){let key=a+'|'+b+'|'+(compact?!logical.has(e.kind):e.kind);if(a!==b&&set.has(a)&&set.has(b)&&!seen.has(key)){seen.add(key);edges.push({a,b,non:!logical.has(e.kind)})}}
if(search){let matches=new Set(ids.filter(i=>(i+' '+by[i].label).toLowerCase().includes(search)));ids=ids.filter(i=>matches.has(i)||edges.some(e=>(matches.has(e.a)&&e.b===i)||(matches.has(e.b)&&e.a===i)));set=new Set(ids);edges=edges.filter(e=>set.has(e.a)&&set.has(e.b))}
let depth=Object.fromEntries(ids.map(i=>[i,0]));for(let j=0;j<ids.length;j++){let change=false;for(let e of edges){if(e.non)continue;let v=Math.min(18,depth[e.a]+1);if(depth[e.b]<v){depth[e.b]=v;change=true}}if(!change)break}let columns={};ids.forEach(i=>(columns[depth[i]]??=[]).push(i));let positions={},maxrows=0;Object.entries(columns).forEach(([c,list])=>{list.sort((a,b)=>(by[a].document||'').localeCompare(by[b].document||'')||a.localeCompare(b));maxrows=Math.max(maxrows,list.length);list.forEach((i,r)=>positions[i]={x:20+Number(c)*272,y:25+r*120})});let w=Math.max(550,(Math.max(0,...Object.values(depth))+1)*272+20),h=Math.max(340,maxrows*120+25);let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><style>.edge{fill:none;stroke:#93a2ad;stroke-width:1.2}.nonlogical{stroke-dasharray:5 4}.nodeText{font:12px system-ui,sans-serif;fill:#152c3c}.nodeId{font:11px system-ui,sans-serif;fill:#4b5965}</style><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#93a2ad"/></marker></defs>`;for(let e of edges){let a=positions[e.a],b=positions[e.b],x=a.x+232,y=a.y+40,xx=b.x,yy=b.y+40;svg+=`<path class="edge ${e.non?'nonlogical':''}" fill="none" stroke="#93a2ad" stroke-width="1.2" ${e.non?'stroke-dasharray="5 4"':''} marker-end="url(#arrow)" d="M${x},${y} C${x+35},${y} ${xx-35},${yy} ${xx},${yy}"/>`}for(let id of ids){let n=by[id],p=positions[id],fill=ext(n)?'#eef0f2':n.side==='historical'?'#fff4d9':'#e8f3fb',stroke=flagged(n)?'#b44336':'#8b9ca8';svg+=`<g class="n ${id===selected?'selected':''}" data-id="${esc(id)}"><title>${esc(n.label)}</title><rect x="${p.x}" y="${p.y}" width="232" height="99" rx="5" fill="${fill}" stroke="${stroke}" stroke-width="${flagged(n)?2:1}"/><text x="${p.x+10}" y="${p.y+17}" class="nodeId">${esc(id)} · ${fmt(val(id))}${n.cost_status==='rollup_only'?' (rollup)':''}</text>`;wrap(n.label).forEach((s,i)=>svg+=`<text x="${p.x+10}" y="${p.y+37+i*15}" class="nodeText">${esc(s)}</text>`);svg+=`<text x="${p.x+10}" y="${p.y+91}" class="nodeId">${esc(n.document||'retained input')}</text></g>`}svg+='</svg>';$('canvas').innerHTML=svg;$('canvas').querySelectorAll('.n').forEach(n=>n.onclick=()=>detail(n.dataset.id));$('graphSummary').textContent=`Showing ${ids.length} boxes and ${edges.length} arrows. Full bound JSON retains all ${G.nodes.length} nodes and ${G.edges.length} fine edges. Weights use ${$('form').value}; arrows run from prerequisite to consumer.`;tables();if(selected)detail(selected)}
const H=D.headline;$('headline').innerHTML=`<div><b>${H.overall_written.toFixed(2)}×</b>overall written compression</div><div><b>${H.conditional_applications.New_A1.toFixed(2)}×</b>PSL application, given U</div><div><b>${H.conditional_applications.New_A2.toFixed(2)}×</b>PGL application, given U</div><div><b>${H.conditional_applications.New_A3.toFixed(2)}×</b>maniplex application, given U</div>`;$('headline').insertAdjacentHTML('afterend',`<p class="small">Including all required code: ${H.known_written_and_required.toFixed(2)}×. Including optional validation too: ${H.including_optional_validation.toFixed(2)}×. External library and historical program costs remain unknown.</p>`);$('granularity').textContent=G.historical_granularity+' '+G.new_granularity;$('hash').textContent='Bound accounting result SHA-256: '+D.result_sha256;initDocs();['side','doc','gran','context','external','nonlogical','metric','form'].forEach(id=>$(id).onchange=()=>{if(id==='side')initDocs();render()});$('search').oninput=render;$('save').onclick=()=>{let blob=new Blob([$ ('canvas').querySelector('svg').outerHTML],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='topic-e-proof-dependencies.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
</script></html>'''
 (a.out/'explorer.html').write_text(template.replace('__DATA__',payload))
 # A collapsed Graphviz representation is also portable, although Graphviz is not needed by HTML.
 parent={c:n['id'] for n in dag['nodes'] for c in n.get('children',[])};by={n['id']:n for n in dag['nodes']};visible={n['id'] for n in dag['nodes'] if n['id'] not in parent and (n['category'] in ['theorem_proof','substantive_unnumbered_proof','named_result_statement_and_proof','named_result_aggregate','required_computation','optional_validation','retained_statement','external_proof'])}
 dot=['digraph proofs {','rankdir=LR;','graph [fontname="Helvetica",label="Paired proof dependencies — documentary historical arrows retain qualifications",labelloc=t];','node [shape=box,style="rounded,filled",fontname="Helvetica",fontsize=10];']
 for id in sorted(visible):
  n=by[id];cost=costs.get(id,{}).get('NFC',{}).get('characters_without_whitespace');label=id+'\\n'+n['label']+'\\n'+('unknown retained cost' if cost is None else str(cost)+' NFC nonspace chars');color='#fff4d9' if n['side']=='historical' else '#e8f3fb';dot.append(json.dumps(id)+' [label='+json.dumps(label,ensure_ascii=False)+',fillcolor="'+color+'"];')
 seen=set()
 for e in dag['edges']:
  if e['kind']=='result_assembly':continue
  src,dst=parent.get(e['prerequisite'],e['prerequisite']),parent.get(e['consumer'],e['consumer'])
  if src in visible and dst in visible and src!=dst and (src,dst) not in seen:
   seen.add((src,dst));style='' if e['kind'] in dag['logical_edge_kinds'] else ' [style=dashed]';dot.append(json.dumps(src)+' -> '+json.dumps(dst)+style+';')
 dot.append('}');(a.out/'overview.dot').write_text('\n'.join(dot)+'\n')
 print(json.dumps(dict(html_bytes=(a.out/'explorer.html').stat().st_size,dot_nodes=len(visible),dot_edges=len(seen),all_fine_edges=len(dag['edges']),primary_text_exported=False)))
if __name__=='__main__':main()
